args.TargetContent:
"        async function selectAsset(assetClass) {
            activeAsset = assetClass;
            activeAdapter = adaptersByAsset[assetClass][0];

            highlightAssetCard(assetClass);
            populateAdapterSelect(assetClass, activeAdapter);
            updateUIContext();

            try {
                await fetch(API_BASE + '/api/system_state', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({active_asset: activeAsset, active_adapter: activeAdapter})
                });
                showActionToast(`Asset context: ${assetClass.toUpperCase()} (Adapter: ${activeAdapter.toUpperCase()})`);
                fetchStatus();
            } catch (err) {
                showActionToast(`Error: ${err.message}`);
            }
        }"
